class Statue : public Entity {
public:
  Statue(int delay) : frames_(0), delay_(delay) {}

  virtual void update() {
    if (++frames_ == delay_) {
      shootLightning();
      // Reset the timer.
      frames_ = 0;
    }
  }

private:
  int frames_;
  int delay_;
  void shootLightning() { /* Shoot the lightning... */ }
};

void Skeleton::update(double elapsed) {
  if (patrollingLeft_) {
    x -= elapsed;
    if (x <= 0) {
      patrollingLeft_ = false;
      x = -x;
    }
  } else {
    x += elapsed;
    if (x >= 100) {
      patrollingLeft_ = true;
      x = 100 - (x - 100);
    }
  }
}

void Entity::update() {
  // Forward to state object.
  state_->update();
}
